# Analyze which columns have ALL 1s transform to ALL 2s
input_demot = input_demo
output_demot = output_demo

columns_all_one_to_two = []
columns_mixed = []

for col in range(29):
    # Find positions with input=1 and output=2
    ones_to_twos = []
    ones_to_ones = []

    for row in range(7):
        if input_demot[row][col] == 1:
            if output_demot[row][col] == 2:
                ones_to_twos.append(row)
            else:
                ones_to_ones.append(row)

    if len(ones_to_twos) == len(input_demot[:,col] if all(x==1 for x in input_demot[:,col]) else 0):
        # Mark if all 1s in this column become 2
        if input_demot[:,col] and all(x==1 for x in input_demot[:7,col]):
            columns_all_one_to_two.append(col)
        # Check if it's mixed
    if len(ones_to_twos) > 0 and len(ones_to_ones) > 0:
        columns_mixed.append(col)

    if col in columns_all_one_to_two:
        print(f"Column {col}: all 1s -> 2")
        print(f"  Input column: {input_demot[:7,col]}")
        print(f"  Output column: {output_demot[:7,col]}")

print(f"\nColumns that are fully 1s in input: {[c for c in range(29) if all(input_demot[r,c]==1 for r in range(7))]}")

# Test the hypothesis: 
# 1. If a column is entirely 1s, all 1s in that column become 2s
# 2. If a cell is in row 6 and is 1, it becomes 2
# 3. Otherwise 1s stay 1s

def expected_transform(in_grid):
    rows, cols = len(in_grid), len(in_grid[0])
    result = [row[:] for row in in_grid]

    # First, identify columns that are all 1s
    all_one_cols = set()
    for col in range(cols):
        if all(in_grid[row][col] == 1 for row in range(rows)):
            all_one_cols.add(col)

    # Apply transformations
    for row in range(rows):
        for col in range(cols):
            if in_grid[row][col] == 1:
                if col in all_one_cols:
                    result[row][col] = 2
                elif row == rows - 1:  # Last row (row 6)
                    result[row][col] = 2

    return result

# Test on demo
expected = expected_transform(input_demo)
match = expected == output_demo
print(f"Pattern matches: {match}")

if not match:
    for row in range(7):
        for col in range(29):
            if expected[row][col] != output_demo[row][col]:
                print(f"Mismatch at ({row},{col}): expected {expected[row][col]}, got {output_demo[row][col]}")

